router.route('/players').get((req, res) => {
  const title = req.query.title;

  Db.getAll(title, (err, data) => {
    if (err)
      res.status(500).send({
        message:
          err.message || "Some error occurred while retrieving players."
      });
    else res.send(data);
  });
})

const getEngineForLocalAsyncCalls = (cmd) => {
    const engineResHolder = [''];
    const res = {
        engineResHolder : engineResHolder,
        write : (oneString) => {
            //console.log('RSP engine from local: ',oneString)
            engineResHolder[0]+=oneString;
            },
        getStdin : () => {
            //console.log('sending cmd to local engine')
            return child.stdin;
        },
        isEngineOn : () => isEngineOn,
        isEngineStarting : () => isEngineOn && isEngineStarting,
        isFirstCommand : true
    }
    if(!isEngineOn) {
        console.log('Need to start engine, go');
        resetEngine();
        return null;
    } else if (isEngineOn && child && child.stdin) {
        if (cmd) {
            console.log('send cmd to engine: #', cmd, "#");

            currentRes = res;
            child.stdin.write("\n" + cmd);
            lastCMD = new Date().getTime();
        } else {
            console.log('NO cmd to engine: #', cmd, "#");
        }
    } else {
        console.log('but engine was dead ', isEngineOn, !!child );
    }
    return res;
};
